/** Shared ATLAS projection contracts, schema1.0.0. Credentials and document contents are excluded. */
export type SourceState = 'UNCONNECTED'|'CONNECTING'|'CONNECTED'|'STALE'|'ERROR';
export type ReviewState = 'DRAFT'|'VERIFIED_EXISTING'|'REVIEW_REQUIRED'|'APPROVED'|'QUARANTINED'|'ARCHIVED';
export type ApplicationState = 'DISCOVERED'|'QUALIFIED'|'PREPARING'|'IN_PROGRESS'|'AWAITING_USER'|'UNKNOWN_OUTCOME'|'SUBMITTED_VERIFIED'|'REJECTED'|'WITHDRAWN'|'CLOSED';
export type OutreachState = 'NOT_STARTED'|'CONTACT_UNAVAILABLE'|'CONTACT_RESEARCHED'|'DRAFTED'|'SENT_VERIFIED'|'SEND_UNKNOWN'|'FAILED'|'RESPONDED';
export type AgentRunState = 'NOT_CONFIGURED'|'QUEUED'|'RUNNING'|'WAITING_USER'|'PARTIALLY_COMPLETED'|'COMPLETED'|'FAILED'|'CANCELLED';
export type Agent = 'PULSAR'|'NEBULA'|'MANUAL';
export type ISODateTime = string;
export interface SourceHealth { source_id:string;connection_state:SourceState;last_success_at:ISODateTime|null;data_watermark:string|null;error_code:string|null;schema_version:'1.0.0' }
export interface CandidateFact { fact_id:string;field:string;approved_value:string|number|boolean|null;source_file_id:string;review_status:ReviewState;verified_at:ISODateTime|null;version:number;allow_agents?:Agent[];evidence_refs?:string[] }
export interface Project { project_id:string;name:string;contribution:string;maturity:'PROPOSED'|'DESIGNED'|'PROTOTYPE'|'TESTED'|'DEPLOYED';evidence_file_ids:string[];approval_status:ReviewState;version:number;source_ref?:string }
export interface CVRevision { cv_id:string;variant:string;role_family:string;file_id:string;checksum:string;version:number;approval_status:ReviewState;created_at:ISODateTime;supersedes_id:string|null;name?:string;file_type?:string;last_used_at?:ISODateTime|null;source_ref?:string }
export interface Application { application_id:string;job_key:string;agent:Agent;employer:string;role:string;country:string;status:ApplicationState;receipt_ref:string|null;cv_id:string|null;sponsorship_status:'ROLE_CONFIRMED'|'EMPLOYER_LICENSE_ONLY'|'UNKNOWN'|'NOT_AVAILABLE';last_updated_at:ISODateTime;job_url?:string|null;cv_version?:number;submitted_at?:ISODateTime|null;submission_attempted_at?:ISODateTime|null;assessment_ref?:string|null;interview_ref?:string|null;pack_ready?:boolean;evidence_refs?:string[] }
export interface Outreach { outreach_id:string;application_id:string|null;recipient_ref:string;gmail_message_id:string|null;attachment_cv_id:string|null;status:OutreachState;sent_at:ISODateTime|null;provider_message_ref?:string|null;updated_at?:ISODateTime;agent?:Agent;channel?:'Gmail'|'Outlook';possibly_linked?:boolean;evidence_refs?:string[] }
export interface Exception { exception_id:string;reason:string;application_id:string|null;manual_action:string;source_task_url:string|null;status:'OPEN'|'RESOLVED';created_at:ISODateTime;last_updated_at:ISODateTime;platform_approval:boolean }
export interface AgentRun { run_id:string;agent:Agent;requested_units:number;verified_submissions:number;full_units:number;blocked:number;started_at:ISODateTime|null;last_checkpoint_at:ISODateTime|null;state:AgentRunState;in_progress?:number;skipped?:number;budget?:{max_units:number;max_minutes:number};pause_scope?:'ONE_VACANCY'|'WORK_PLATFORM';exceptions?:Exception[] }
export interface AuditEvent { event_id:string;entity_id:string;event_type:string;actor:string;timestamp:ISODateTime;source_ref:string;before_hash:string|null;after_hash:string|null;entity_type?:string;summary?:string }
export interface Review { review_id:string;source_file_id:string;claim_type:string;detected_value:string|number|boolean|null;conflict_ref:string|null;state:ReviewState;decision_actor:string|null;decision_at:ISODateTime|null;original_source_file_id?:string;source_ref?:string;approved_value?:string|number|boolean|null;previous_version?:number;proposed_version?:number;impacted_ids?:string[];reason?:string;diff?:{field:string;before:unknown;after:unknown;kind:'EXISTING'|'CONFLICT'|'UNSUPPORTED'}[] }
export interface Configuration {key:string;value:unknown;effective_from:ISODateTime;version:number;approved_by:string}
export interface AtlasSnapshot { schema_version:'1.0.0';mode:'UNCONNECTED'|'DEMO'|'LIVE';label?:string;generated_at:ISODateTime|null;complete:boolean;source_health:SourceHealth;window:{from:string|null;to:string|null;timezone:'Europe/London'};watermark:string|null;agents:{ATLAS:string;PULSAR:string;NEBULA:string;integration:string};collections:{candidate_facts:CandidateFact[];project_index:Project[];cv_registry:CVRevision[];applications:Application[];outreach:Outreach[];runs:AgentRun[];events:AuditEvent[];review_queue:Review[];source_health:SourceHealth[];configuration:Configuration[]} }
export type MetricKey = 'unique_approaches'|'application_processes'|'pending_outcome'|'todays_completions'|'rejected_closed'|'assessments'|'unique_outreach'|'unmatched_outreach'|'potentially_linked'|'withheld_records'|'ready_packs'|'interview_invitations'|'sent_verified'|'send_unknown'|'failed_routes'|'responded'|'attempts'|'strict_full_units';
export interface Metric {value:number|null;record_ids:string[];definition_id:MetricKey}
export interface MetricDefinition {id:string;label:string;inclusion:string;exclusion:string;collection:string;timezone:'Europe/London';scope:'CURRENT_INVENTORY'|'REPORTING_WINDOW';version:'1.0.0'}
export interface DataProvider {getSnapshot(options?:{state?:SourceState;empty?:boolean}):Promise<AtlasSnapshot>}


